-- Generated by dbml CLI

CREATE TABLE users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    identity_provider TEXT,
    external_subject TEXT,
    email TEXT,
    display_name TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    disabled_at TIMESTAMPTZ,
    (identity_provider, EXTERNAL_SUBJECT) UNIQUE
);

CREATE TABLE organisations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT,
    slug TEXT,
    status TEXT DEFAULT 'active',
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE memberships (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organisation_id UUID,
    user_id UUID,
    role TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    (organisation_id, USER_ID) UNIQUE,
    (organisation_id, ID) UNIQUE
);

CREATE TABLE studies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organisation_id UUID,
    name TEXT,
    description TEXT,
    status TEXT DEFAULT 'active',
    created_by UUID,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    archived_at TIMESTAMPTZ,
    (organisation_id, ID) UNIQUE,
    (organisation_id, CREATED_AT,,
    (organisation_id, STATUS,
);

CREATE TABLE datasets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organisation_id UUID,
    study_id UUID,
    name TEXT,
    description TEXT,
    status TEXT DEFAULT 'pending_upload',
    format TEXT DEFAULT 'npy',
    storage_key TEXT,
    object_version TEXT,
    checksum_sha256 TEXT,
    file_size_bytes BIGINT,
    sampling_frequency_hz FLOAT8,
    channel_count INTEGER,
    sample_count BIGINT,
    duration_seconds FLOAT8,
    channel_names JSONB,
    channel_units JSONB,
    metadata JSONB DEFAULT {}'::jsonb,
    validation_report JSONB,
    source_description TEXT,
    uploaded_by UUID,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    validated_at TIMESTAMPTZ,
    archived_at TIMESTAMPTZ,
    (organisation_id, ID) UNIQUE,
    (organisation_id, STUDY_ID,,
    (organisation_id, STATUS,
);

CREATE TABLE upload_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organisation_id UUID,
    dataset_id UUID,
    created_by UUID,
    status TEXT DEFAULT 'created',
    object_key TEXT,
    expected_size_bytes BIGINT,
    expected_checksum_sha256 TEXT,
    expires_at TIMESTAMPTZ,
    finalised_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    manifest JSONB DEFAULT {}'::jsonb,
    (organisation_id, STATUS,,
    (organisation_id, DATASET_ID)
);

CREATE TABLE analysis_jobs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organisation_id UUID,
    dataset_id UUID,
    requested_by UUID,
    analysis_type TEXT,
    algorithm_version TEXT,
    parameters JSONB DEFAULT {}'::jsonb,
    status TEXT DEFAULT 'queued',
    attempt_count INTEGER DEFAULT 0,
    max_attempts INTEGER DEFAULT 3,
    error_code TEXT,
    error_message TEXT,
    idempotency_key TEXT,
    requested_at TIMESTAMPTZ DEFAULT now(),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    lease_expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    (organisation_id, REQUESTED_AT,,
    (organisation_id, STATUS,,
    (organisation_id, DATASET_ID,
);

CREATE TABLE analysis_results (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organisation_id UUID,
    job_id UUID,
    dataset_id UUID,
    dataset_checksum_sha256 TEXT,
    algorithm_version TEXT,
    result_schema_version TEXT,
    results JSONB,
    provenance JSONB DEFAULT {}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT now(),
    (organisation_id, DATASET_ID,
);

CREATE TABLE outbox_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organisation_id UUID,
    event_type TEXT,
    aggregate_type TEXT,
    aggregate_id UUID,
    payload JSONB DEFAULT {}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT now(),
    published_at TIMESTAMPTZ,
    attempt_count INTEGER DEFAULT 0,
    next_attempt_at TIMESTAMPTZ,
    last_error_code TEXT
);

CREATE TABLE idempotency_keys (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organisation_id UUID,
    user_id UUID,
    operation TEXT,
    key TEXT,
    request_hash TEXT,
    response_status INTEGER,
    response_body JSONB,
    resource_id UUID,
    created_at TIMESTAMPTZ DEFAULT now(),
    expires_at TIMESTAMPTZ,
    (organisation_id, USER_ID, UNIQUE
);

CREATE TABLE audit_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organisation_id UUID,
    actor_user_id UUID,
    action TEXT,
    resource_type TEXT,
    resource_id UUID,
    request_id TEXT,
    metadata JSONB DEFAULT {}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT now(),
    (organisation_id, CREATED_AT,,
    (resource_type, RESOURCE_ID)
);

CREATE TABLE schema_migrations (
    version TEXT PRIMARY KEY,
    checksum TEXT,
    applied_at TIMESTAMPTZ DEFAULT now()
);

